@page "/book-appointment"
@rendermode InteractiveServer
@using sv_8a7f5141c0c7427cbfba27f364b80786.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

@if (isSubmitted)
{
    <div class="alert alert-success mt-3">
        <h4>Appointment Confirmed!</h4>
        <p><strong>Patient:</strong> @model.PatientName</p>
        <p><strong>Doctor:</strong> @model.Doctor</p>
        <p><strong>Date:</strong> @model.AppointmentDate?.ToString("D")</p>
        <p><strong>Time:</strong> @model.TimeSlot</p>
        <button class="btn btn-primary" @onclick="ResetForm">Book Another</button>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        @* ===== STEP 1 ===== *@
        <fieldset>
            <legend>Patient Information</legend>

            <div class="mb-3">
                <label class="form-label" for="patientName">Patient Name</label>
                <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
                <ValidationMessage For="() => model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <InputText id="email" class="form-control" @bind-Value="model.Email" />
                <ValidationMessage For="() => model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
                <ValidationMessage For="() => model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="insurance">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </div>

            @if (!showStep2)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
                    @(isProcessing ? "Checking..." : "Continue to Step 2")
                </button>
            }
        </fieldset>

        @* ===== STEP 2 ===== *@
        @if (showStep2)
        {
            <fieldset class="mt-4">
                <legend>Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label" for="doctor">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                                 @bind-Value:after="OnDoctorChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="date">Appointment Date</label>
                    <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                               @bind-Value:after="OnDateChanged" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                    @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                    {
                        <div class="text-danger">Date must be in the future.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeSlot">Time Slot</label>
                    <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                    @if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue && availableSlots.Count == 0)
                    {
                        <div class="text-warning">No slots available for this doctor and date.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
                    <ValidationMessage For="() => model.ReasonForVisit" />
                    <small class="text-muted">@((model.ReasonForVisit?.Length ?? 0))/500 characters</small>
                </div>

                <div class="d-flex gap-2">
                    <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
                    <button type="submit" class="btn btn-success" disabled="@isProcessing">
                        @(isProcessing ? "Checking Availability..." : "Check Availability & Book")
                    </button>
                </div>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = null!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitted;
    private bool isProcessing;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        var isValid = true;
        var step1Model = new Step1Model
        {
            PatientName = model.PatientName,
            Email = model.Email,
            Phone = model.Phone,
            InsuranceProvider = model.InsuranceProvider
        };
        var step1Context = new EditContext(step1Model);
        if (!step1Context.Validate())
        {
            // Transfer errors to main context
            customValidator?.ClearErrors();
            var errors = new Dictionary<string, List<string>>();
            foreach (var field in Step1Fields)
            {
                var messages = step1Context.GetValidationMessages(step1Context.Field(field)).ToList();
                if (messages.Count > 0)
                {
                    errors[field] = messages;
                    isValid = false;
                }
            }
            if (!isValid)
            {
                customValidator?.DisplayErrors(errors);
            }
            return;
        }

        showStep2 = true;
    }

    private async Task OnDoctorChanged()
    {
        model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!editContext.Validate())
            return;

        // Additional client-side check: date must be in the future
        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                [nameof(AppointmentModel.AppointmentDate)] = ["Appointment date must be in the future."]
            });
            return;
        }

        isProcessing = true;
        try
        {
            // Server-side business rule validation
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (serverErrors.Count > 0)
            {
                customValidator?.DisplayErrors(serverErrors);
                return;
            }

            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        customValidator?.ClearErrors();
    }

    private void ResetForm()
    {
        model = new();
        editContext = new EditContext(model);
        showStep2 = false;
        isSubmitted = false;
        availableSlots = [];
    }
}

