+            Phone = model.Phone,
+            InsuranceProvider = model.InsuranceProvider
+        };
+        var step1Context = new EditContext(step1Model);
+        if (!step1Context.Validate())
+        {
+            // Transfer errors to main context
+            customValidator?.ClearErrors();
+            var errors = new Dictionary<string, List<string>>();
+            foreach (var field in Step1Fields)
+            {
+                var messages = step1Context.GetValidationMessages(step1Context.Field(field)).ToList();
+                if (messages.Count > 0)
+                {
+                    errors[field] = messages;
+                    isValid = false;
+                }
+            }
+            if (!isValid)
+            {
+                customValidator?.DisplayErrors(errors);
+            }
+            return;
+        }
+
+        showStep2 = true;
+    }
+
+    private async Task OnDoctorChanged()
+    {
+        model.TimeSlot = null;
+        await LoadSlots();
+    }
+
+    private async Task OnDateChanged()
+    {
+        model.TimeSlot = null;
+        await LoadSlots();
+    }
+
+    private async Task LoadSlots()
+    {
+        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
+                model.Doctor, model.AppointmentDate.Value);
+        }
+        else
+        {
+            availableSlots = [];
+        }
+    }
+
+    private async Task HandleSubmit()
+    {
+        customValidator?.ClearErrors();
+
+        if (!editContext.Validate())
+            return;
+
+        // Additional client-side check: date must be in the future
+        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
+            {
+                [nameof(AppointmentModel.AppointmentDate)] = ["Appointment date must be in the future."]
+            });
+            return;
+        }
+
+        isProcessing = true;
+        try
+        {
+            // Server-side business rule validation
+            var serverErrors = await AppointmentService.ValidatePatientAsync(
+                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);
+
+            if (serverErrors.Count > 0)
+            {
+                customValidator?.DisplayErrors(serverErrors);
+                return;
+            }
+
+            isSubmitted = true;
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        customValidator?.ClearErrors();
+    }
+
+    private void ResetForm()
+    {
+        model = new();
+        editContext = new EditContext(model);
+        showStep2 = false;
+        isSubmitted = false;
+        availableSlots = [];
+    }
+}
